/**
 * AryaOS V1 — Stage 05: Action Proposal & Execution Adapter
 *
 * Implements the operational bridge:
 * Intent -> Action Proposal -> User Confirmation -> Execution Adapter -> Memory Event
 *
 * Adheres strictly to the honest execution boundary:
 * Consequential backend capabilities return 'PLANNED' rather than falsely claiming 'EXECUTED'.
 */

import {
  ActionProposal,
  ActionResult,
  MemoryEvent,
  Command,
  ActionClass,
} from '../types/spatialCommand';
import { memoryArchiveService } from './memoryArchiveService';

/**
 * In-memory ledger of semantic memory events generated by command actions.
 * Never mutates Three.js spatial scene geometry.
 */
let MEMORY_EVENTS_STORE: MemoryEvent[] = [
  {
    id: 'EVT-INIT-001',
    type: 'STAGE_INITIALIZED',
    sourceMemoryId: 'MEM-0021',
    sourceMemoryTitle: 'The Astrolabe Core Ignition Event',
    action: 'TRACE_MEMORY',
    timestamp: new Date().toISOString(),
    status: 'RECORDED',
    resultSummary: 'Stage 05 Spatial Intelligence Command Layer initialized and synchronized with Stage 03 Memory substrate.',
    relatedEntities: ['Arya Core', 'Spatial Engine'],
  },
];

export const actionProposalService = {
  /**
   * Generates a structured ActionProposal from a parsed Command.
   */
  createProposal(command: Command): ActionProposal | null {
    const ctx = command.context;
    const sourceMem = ctx?.activeMemory || (command.targetMemoryId ? memoryArchiveService.getMemoryById(command.targetMemoryId) : null);
    const relatedCount = ctx?.directRelationships.length || (sourceMem ? sourceMem.relationships.length : 0);
    const entitiesCount = ctx?.sharedEntities.length || (sourceMem ? sourceMem.entities.length : 0);
    const decisionsCount = ctx?.predecessorDecisions.length || 0;

    const id = `ACT-${Date.now()}`;
    const createdAt = new Date().toISOString();

    switch (command.intent) {
      case 'CREATE_RESEARCH_TASK': {
        const title = sourceMem ? `Research: ${sourceMem.title}` : `Research: ${command.rawInput}`;
        return {
          id,
          actionClass: 'RESEARCH',
          title,
          description: sourceMem
            ? `Dispatch autonomous research task to investigate deeper technical precedents and constraints anchored to ${sourceMem.id}.`
            : `Dispatch research task investigating: "${command.rawInput}".`,
          sourceMemoryId: sourceMem?.id,
          sourceMemoryTitle: sourceMem?.title,
          contextSummary: {
            relatedCount,
            entitiesCount,
            decisionsCount,
            notes: 'Requires multi-agent research pool dispatch.',
          },
          executionType: 'BACKEND_ADAPTER',
          status: 'PROPOSED',
          createdAt,
          payload: {
            taskType: 'RESEARCH',
            query: command.rawInput,
            sourceMemory: sourceMem?.id,
            entities: sourceMem?.entities || [],
            priority: sourceMem ? sourceMem.importance : 0.8,
          },
        };
      }

      case 'GENERATE_PRODUCTION_PLAN': {
        const title = sourceMem ? `Production Plan: ${sourceMem.title}` : 'Generate Multi-Shot Production Plan';
        return {
          id,
          actionClass: 'CREATE_WORKFLOW',
          title,
          description: sourceMem
            ? `Compile a multi-shot sequence synthesis plan enforcing the continuity and lighting constraints established in ${sourceMem.id}.`
            : 'Compile production sequence plan based on current memory archive context.',
          sourceMemoryId: sourceMem?.id,
          sourceMemoryTitle: sourceMem?.title,
          contextSummary: {
            relatedCount,
            entitiesCount,
            decisionsCount,
            notes: 'Stages sequence compilation into the OpenMontage corridor adapter.',
          },
          executionType: 'BACKEND_ADAPTER',
          status: 'PROPOSED',
          createdAt,
          payload: {
            workflowType: 'PRODUCTION_PLAN_COMPILATION',
            sourceMemoryId: sourceMem?.id,
            targetShotsCount: 8,
          },
        };
      }

      case 'OPEN_MEMORY': {
        const targetId = command.targetMemoryId || 'MEM-0001';
        const targetMem = memoryArchiveService.getMemoryById(targetId);
        return {
          id,
          actionClass: 'OPEN_MEMORY',
          title: `Inspect Memory: ${targetMem?.title || targetId}`,
          description: `Focus camera and open semantic detail inspection drawer for ${targetId}.`,
          sourceMemoryId: sourceMem?.id,
          sourceMemoryTitle: sourceMem?.title,
          targetMemoryId: targetId,
          targetVitrineId: command.targetVitrineId,
          contextSummary: {
            relatedCount: targetMem?.relationships.length || 0,
            entitiesCount: targetMem?.entities.length || 0,
            decisionsCount: 0,
          },
          executionType: 'FRONTEND_DIRECT',
          status: 'PROPOSED',
          createdAt,
        };
      }

      case 'TRACE_HISTORY': {
        return {
          id,
          actionClass: 'TRACE_MEMORY',
          title: sourceMem ? `Trace History: ${sourceMem.title}` : 'Trace System Chronological History',
          description: sourceMem
            ? `Trace causal predecessor/successor lineage and animate 3D relationship tethers for ${sourceMem.id}.`
            : 'Trace sequential milestone path across all 24 spatial archive crystals.',
          sourceMemoryId: sourceMem?.id,
          sourceMemoryTitle: sourceMem?.title,
          targetMemoryId: sourceMem?.id,
          contextSummary: {
            relatedCount,
            entitiesCount,
            decisionsCount,
            notes: 'Highlights temporal chain in HUD and 3D splines.',
          },
          executionType: 'FRONTEND_DIRECT',
          status: 'PROPOSED',
          createdAt,
        };
      }

      case 'SHOW_RELATED': {
        return {
          id,
          actionClass: 'FILTER_MEMORY',
          title: sourceMem ? `Show Related: ${sourceMem.title}` : 'Highlight Associated Vitrine Graph',
          description: `Filter spatial HUD and activate 3D connection splines to all associated records.`,
          sourceMemoryId: sourceMem?.id,
          sourceMemoryTitle: sourceMem?.title,
          contextSummary: {
            relatedCount,
            entitiesCount,
            decisionsCount,
          },
          executionType: 'FRONTEND_DIRECT',
          status: 'PROPOSED',
          createdAt,
        };
      }

      case 'SHOW_UNRESOLVED': {
        return {
          id,
          actionClass: 'FILTER_MEMORY',
          title: 'Isolate Unresolved Items & Arbitration Boundaries',
          description: 'Filter archive to highlight vitrines with active conflict or confidence < 85%.',
          contextSummary: {
            relatedCount: 0,
            entitiesCount: 0,
            decisionsCount: 0,
            notes: 'Filters bottom registry and emphasizes matching 3D crystals.',
          },
          executionType: 'FRONTEND_DIRECT',
          status: 'PROPOSED',
          createdAt,
        };
      }

      case 'SWITCH_CAMERA': {
        return {
          id,
          actionClass: 'SWITCH_CAMERA',
          title: `Switch Viewport: ${command.targetCamera || 'CAM_CinematicHero'}`,
          description: `Transition spatial camera to locked specification ${command.targetCamera || 'CAM_CinematicHero'}.`,
          targetCamera: command.targetCamera,
          contextSummary: {
            relatedCount: 0,
            entitiesCount: 0,
            decisionsCount: 0,
          },
          executionType: 'FRONTEND_DIRECT',
          status: 'PROPOSED',
          createdAt,
        };
      }

      default:
        return null;
    }
  },

  /**
   * Executes or plans a confirmed ActionProposal.
   * Consequential backend actions return status: 'PLANNED' via adapter boundary.
   */
  executeProposal(proposal: ActionProposal): ActionResult {
    const timestamp = new Date().toISOString();

    // Consequential backend-dependent actions:
    if (proposal.executionType === 'BACKEND_ADAPTER') {
      const event: MemoryEvent = {
        id: `EVT-${Date.now()}`,
        type: `ACTION_PLANNED_${proposal.actionClass}`,
        sourceMemoryId: proposal.sourceMemoryId,
        sourceMemoryTitle: proposal.sourceMemoryTitle,
        action: proposal.actionClass,
        timestamp,
        status: 'PLANNED',
        resultSummary: `Action proposal "${proposal.title}" staged as PLANNED. Execution contract prepared for backend orchestrator dispatch.`,
        relatedEntities: ['Arya Core', 'Orchestration Gateway'],
        metadata: proposal.payload,
      };

      this.recordMemoryEvent(event);

      return {
        actionId: proposal.id,
        success: true,
        status: 'PLANNED',
        message: `Action planned: "${proposal.title}". Execution payload staged for background provider dispatch (Status: PLANNED).`,
        outputData: proposal.payload,
        memoryEvent: event,
        timestamp,
      };
    }

    // Direct frontend-executable actions:
    const event: MemoryEvent = {
      id: `EVT-${Date.now()}`,
      type: `ACTION_EXECUTED_${proposal.actionClass}`,
      sourceMemoryId: proposal.sourceMemoryId,
      sourceMemoryTitle: proposal.sourceMemoryTitle,
      action: proposal.actionClass,
      timestamp,
      status: 'EXECUTED',
      resultSummary: `Successfully executed spatial action "${proposal.title}".`,
      relatedEntities: ['Spatial Interface', 'Operator'],
      metadata: { targetMemoryId: proposal.targetMemoryId, targetCamera: proposal.targetCamera },
    };

    this.recordMemoryEvent(event);

    return {
      actionId: proposal.id,
      success: true,
      status: 'EXECUTED',
      message: `Action executed: "${proposal.title}".`,
      outputData: { targetMemoryId: proposal.targetMemoryId, targetCamera: proposal.targetCamera },
      memoryEvent: event,
      timestamp,
    };
  },

  /**
   * Appends an event to the semantic memory ledger.
   */
  recordMemoryEvent(event: MemoryEvent): void {
    MEMORY_EVENTS_STORE = [event, ...MEMORY_EVENTS_STORE.slice(0, 49)];
  },

  /**
   * Retrieves all recorded memory events.
   */
  getMemoryEvents(): MemoryEvent[] {
    return MEMORY_EVENTS_STORE;
  },

  /**
   * Resets the events ledger (useful for test isolates).
   */
  resetMemoryEvents(): void {
    MEMORY_EVENTS_STORE = [];
  },
};
